sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    //MSSTRUSTES-474
    if (isLoading) {
        if (newValue === '') {
            return;
        }
    } else {
        if (newValue === oldValue) {
            return;
        }
    }

    var statusField = 'u_trus_status';
    var complaintValue = 'Complaint';
    var escalationValue = 'Escalation';
    var inquiryValue = 'Inquiry';

    g_form.clearOptions(statusField);

    if (newValue === complaintValue || newValue === inquiryValue) {
		g_form.addOption(statusField, '1', 'Default SLA');
        g_form.addOption(statusField, '2', 'Approach Determination');
        g_form.addOption(statusField, '3', 'HSBC only');
        g_form.addOption(statusField, '4', 'BCT only or HSBC and BCT (no PCCW)');
        g_form.addOption(statusField, '5', 'HSBC and PCCW (no BCT)');
        g_form.addOption(statusField, '6', 'Tri Parties (jointly reply with PCCW) - 1st reply');
        g_form.addOption(statusField, '7', 'Tri Parties (jointly reply with PCCW) - subsequent reply');
        g_form.addOption(statusField, '8', 'Tri Parties (individually HSBC reply)');
    }
    else if (newValue === escalationValue) {
		g_form.addOption(statusField, '1', 'Default SLA');
        g_form.addOption(statusField, '9', 'Enrol (ER)');
        g_form.addOption(statusField, '10', 'Enrol (SEP)');
        g_form.addOption(statusField, '11', 'Enrol (others)');
        g_form.addOption(statusField, '12', 'Cont');
        g_form.addOption(statusField, '13', 'Term (not payment)');
        g_form.addOption(statusField, '14', 'Term (payment)');
        g_form.addOption(statusField, '15', 'Payment Recon');
        g_form.addOption(statusField, '16', 'Daily Unit Recon');
        g_form.addOption(statusField, '17', 'Daily SCH Recon');
        g_form.addOption(statusField, '18', 'AML/KYC');
        g_form.addOption(statusField, '19', 'YE');
    }
}
